'use strict';
/* Browser zoom guards; CSS retains ordinary single-finger scrolling. */
(function lockHomeScroll(){
 const apply=()=>{const h=document.getElementById('home');const fit=h&&!h.hidden&&document.documentElement.scrollHeight<=innerHeight+2;document.body.classList.toggle('no-scroll',!!fit);};
 addEventListener('resize',apply);addEventListener('orientationchange',()=>setTimeout(apply,250));
 if(window.ResizeObserver)new ResizeObserver(apply).observe(document.querySelector('.shell'));
 new MutationObserver(apply).observe(document.getElementById('home'),{attributes:true,attributeFilter:['hidden']});
 addEventListener('load',apply);setTimeout(apply,300);
})();
/* Zoom bloccato solo sul campo di gioco (schermata di gioco visibile, nessun pannello aperto).
   Menu, impostazioni, guida e raccolta restano zoomabili per leggere i testi. */
(function preventBrowserZoom(){
 const cancel=e=>{if(e.cancelable)e.preventDefault();};
 const field=()=>{const g=document.getElementById('game');return !!g&&!g.hidden&&document.getElementById('modalBack').hidden;};
 const onField=e=>field()&&!!e.target&&typeof e.target.closest==='function'&&!!e.target.closest('#game');
 for(const type of ['gesturestart','gesturechange','gestureend'])
  document.addEventListener(type,e=>{if(onField(e))cancel(e);},{passive:false});
 for(const type of ['touchstart','touchmove'])
  document.addEventListener(type,e=>{if(e.touches.length>1&&onField(e))cancel(e);},{passive:false});
 document.addEventListener('dblclick',e=>{if(onField(e))cancel(e);},{passive:false});
 document.addEventListener('wheel',e=>{if((e.ctrlKey||e.metaKey)&&onField(e))cancel(e);},{passive:false});
 document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&['+','=','-','_','0','Add','Subtract'].includes(e.key)&&field())cancel(e);
 });
})();

/* Confused Prime 1.9 — all gameplay randomness belongs to Engine; cosmetic effects are separate.
   The stable 36 button elements are never replaced by a board render. */
const Prime = { is(n){if(!Number.isSafeInteger(n)||n<2)return false;if(n===2)return true;if(n%2===0)return false;for(let d=3;d<=Math.sqrt(n);d+=2)if(n%d===0)return false;return true;} };
Prime.factor=function(n){if(!Number.isSafeInteger(n)||n<2)return null;for(let d=2;d<=Math.sqrt(n);d++)if(n%d===0)return d;return n;};
Prime.explain=function(n){if(n<2)return n+' non è primo';if(n===2)return '✓ 2 · unico primo pari';const d=Prime.factor(n);if(d===n)return '✓ Primo · due divisori';return (d===2?'Pari · ':'')+n+' = '+d+' × '+(n/d);};
Prime.twins=(a,b)=>a!==b&&Math.abs(a-b)===2&&Prime.is(a)&&Prime.is(b);
const NORMAL_PACE=[{prime:0,ms:8000},{prime:101,ms:6000},{prime:503,ms:5000},{prime:1009,ms:4000}];
const ATTACK={start:67000,fuse:3000,pair:-3000,triple:-5000,hint:-5000};
class Engine {
 constructor(seed,mode='normal'){this.seed=seed>>>0;this.rng=this.seed;this.mode=mode;this.board=Array(36).fill(0);this.selected=[];this.score=0;this.highest=0;this.remaining=8000;this.arrivalInterval=8000;this.targetInterval=8000;this.paceLevel=0;this.elapsedMs=0;this.found={};this.fusions=0;this.attackRemaining=ATTACK.start;this.endReason=null;this.hintsUsed=0;this.over=false;this.moves=0;this.queue=[];for(let k=0;k<18;k++){const e=this.empty();this.board[e[Math.floor(this.random()*e.length)]]=this.value();}for(let k=0;k<3;k++)this.queue.push(this.value());this.updateHighest();}
 random(){let t=this.rng=(this.rng+0x6D2B79F5)>>>0;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;}
 value(){return 1+Math.floor(this.random()*9);}
 empty(){return this.board.map((v,i)=>v? -1:i).filter(i=>i>=0);}
 adjacent(a,b){return a!==b&&Math.abs(Math.floor(a/6)-Math.floor(b/6))<=1&&Math.abs(a%6-b%6)<=1;}
 neighbors(i){return this.board.map((v,j)=>v&&this.adjacent(i,j)?j:-1).filter(j=>j>=0);}
 select(i){if(this.over||!this.board[i])return false;if(!this.selected.length){this.selected=[i];return true;}const c=this.selected[0];if(i===c){this.selected=[];return true;}if(!this.adjacent(c,i))return false;const k=this.selected.indexOf(i);if(k>=0)this.selected.splice(k,1);else this.selected.push(i);return true;}
 options(sel=this.selected){const vals=sel.map(i=>this.board[i]),sum=vals.reduce((a,b)=>a+b,0),n=sel.length;const valid=n>0&&new Set(sel).size===n&&vals.every(v=>v>0)&&sel.slice(1).every(i=>this.adjacent(sel[0],i));const equal=valid&&vals.every(v=>v===vals[0]);return {sum,n,fuse:valid&&n>=2&&Prime.is(sum),pair:equal&&n===2&&Prime.is(vals[0]),triple:equal&&n===3,mergeGain:sum*sum,cost:n? n*vals[0]*vals[0]:0};}
 updateHighest(){for(const v of this.board)if(Prime.is(v))this.highest=Math.max(this.highest,v);}
 spawn(){const e=this.empty();if(!e.length){this.over=true;this.endReason='full';return -1;}const i=e[Math.floor(this.random()*e.length)];this.board[i]=this.queue.shift();this.queue.push(this.value());this.updateHighest();if(e.length===1){this.over=true;this.endReason='full';}return i;}
 act(kind){if(this.over)return null;const o=this.options();if(!o[kind])return null;const sel=this.selected.slice(),center=sel[0],delta=kind==='fuse'?o.mergeGain:-o.cost,oldCenter=this.board[center];for(const i of sel)this.board[i]=0;if(kind==='fuse')this.board[center]=o.sum;this.score+=delta;this.selected=[];this.moves++;this.updateHighest();if(kind==='fuse'){this.found[o.sum]=(this.found[o.sum]||0)+1;this.fusions++;}const paceChange=this.schedulePace();const arrived=this.spawn();const timeDelta=this.mode==='attack'?ATTACK[kind]:0;this.changeTime(timeDelta);return {kind,sel,center,delta,result:o.sum,arrived,timeDelta,paceChange,oldCenter,twin:kind==='fuse'&&Prime.twins(oldCenter,o.sum)};}
 changeTime(ms){if(this.mode!=='attack')return;this.attackRemaining=Math.max(0,this.attackRemaining+ms);if(this.attackRemaining<=0){this.over=true;this.endReason='time';}}
 requestHint(){if(this.over||this.mode==='attack'&&this.attackRemaining<=-ATTACK.hint)return null;const h=this.hint();if(!h)return null;this.changeTime(ATTACK.hint);this.hintsUsed++;return h;}
 schedulePace(){if(this.mode!=='normal')return null;let level=0;for(let i=1;i<NORMAL_PACE.length;i++)if(this.highest>=NORMAL_PACE[i].prime)level=i;if(level<=this.paceLevel)return null;this.paceLevel=level;this.targetInterval=NORMAL_PACE[level].ms;return {level,interval:this.targetInterval,threshold:NORMAL_PACE[level].prime};}
 tick(ms){if(this.over)return -1;ms=Math.max(0,ms);this.elapsedMs+=this.mode==='attack'?Math.min(ms,this.attackRemaining):ms;if(this.mode==='training')return -1;if(this.mode==='attack'){this.changeTime(-ms);if(this.over)return -1;}this.remaining-=ms;if(this.remaining<=0){const arrived=this.spawn();this.arrivalInterval=this.targetInterval;this.remaining+=this.arrivalInterval;return arrived;}return -1;}
 hint(){let best=null;for(let c=0;c<36;c++){if(!this.board[c])continue;const ns=this.neighbors(c);for(let mask=1;mask<(1<<ns.length);mask++){const sel=[c];for(let j=0;j<ns.length;j++)if(mask&(1<<j))sel.push(ns[j]);const o=this.options(sel);if(o.fuse&&(!best||o.mergeGain>best.gain))best={kind:'fuse',sel,gain:o.mergeGain};}}if(best)return best;for(let c=0;c<36;c++){if(!this.board[c])continue;const ns=this.neighbors(c).filter(i=>this.board[i]===this.board[c]);for(const i of ns){const sel=[c,i],o=this.options(sel);if(o.pair&&(!best||o.cost<best.cost))best={kind:'pair',sel,cost:o.cost};}for(let a=0;a<ns.length;a++)for(let b=a+1;b<ns.length;b++){const sel=[c,ns[a],ns[b]],o=this.options(sel);if(o.triple&&(!best||o.cost<best.cost))best={kind:'triple',sel,cost:o.cost};}}return best;}
}
const modeName=mode=>({normal:'Normale',training:'Allenamento',attack:'Time Attack'})[mode];
const recordKey=mode=>({normal:'bestNormal',training:'bestTrain',attack:'bestAttack'})[mode];
const $=id=>document.getElementById(id),MUSIC=JSON.parse(document.getElementById('musicAssets').textContent),fmt=n=>n.toLocaleString(locale());
let storageOK=true,prefs={language:'en',theme:'confetti',hintsDay:'',hintsUsed:0,sound:true,music:true,musicVolume:.35,soundVolume:.65,haptic:true,reduceMotion:false,tutorial:false,bestNormal:0,bestTrain:0,bestAttack:0};
try{const data=JSON.parse(localStorage.getItem('cbm-primi-v1')||'{}');for(const k of Object.keys(prefs))if(typeof data[k]===typeof prefs[k])prefs[k]=data[k];}catch(_){storageOK=false;}
prefs.musicVolume=Number.isFinite(prefs.musicVolume)?Math.min(1,Math.max(0,prefs.musicVolume)):.35;prefs.soundVolume=Number.isFinite(prefs.soundVolume)?Math.min(1,Math.max(0,prefs.soundVolume)):.65;
function save(){try{localStorage.setItem('cbm-primi-v1',JSON.stringify(prefs));}catch(_){storageOK=false;}$('storageWarning').hidden=storageOK;}

/* ── Temi ─────────────────────────────────────────────────────────────
   I colori vivono solo nel CSS (variabili su [data-theme]). Qui: registro,
   applicazione, salvataggio e lettura dei colori per i soli effetti canvas. */
const THEMES=[
 {id:'auto',name:'Automatico',tag:'Come il dispositivo'},
 {id:'confetti',name:'Confetti',tag:'Chiaro'},
 {id:'menta',name:'Menta',tag:'Chiaro'},
 {id:'sakura',name:'Sakura',tag:'Chiaro'},
 {id:'tramonto',name:'Tramonto',tag:'Chiaro'},
 {id:'carta',name:'Alto contrasto',tag:'Accessibile'},
 {id:'notte',name:'Notte',tag:'Scuro'},
 {id:'oceano',name:'Oceano',tag:'Scuro'},
 {id:'neon',name:'Neon',tag:'Scuro'},
 {id:'terminale',name:'Terminale',tag:'Retrò'}
];
const darkQuery=window.matchMedia?window.matchMedia('(prefers-color-scheme: dark)'):null;
let FX={good:'#b4d77c',goodHi:'#ecffc2',goodLo:'#8da963',bad:'#c9899a',badHi:'#f5e2e7',badLo:'#b46376'},themeTimer;
if(!THEMES.some(t=>t.id===prefs.theme))prefs.theme='confetti';
function resolveTheme(pref){return pref==='auto'?(darkQuery&&darkQuery.matches?'notte':'confetti'):pref;}
function readFx(){const cs=getComputedStyle(document.documentElement),g=(n,d)=>cs.getPropertyValue(n).trim()||d;FX={good:g('--fx-good',FX.good),goodHi:g('--fx-good-hi',FX.goodHi),goodLo:g('--fx-good-lo',FX.goodLo),bad:g('--fx-bad',FX.bad),badHi:g('--fx-bad-hi',FX.badHi),badLo:g('--fx-bad-lo',FX.badLo)};}
function applyTheme(pref=prefs.theme,animate=false){
 const root=document.documentElement,id=resolveTheme(pref);
 if(animate&&!reducedMotion()){root.classList.add('theme-anim');clearTimeout(themeTimer);themeTimer=setTimeout(()=>root.classList.remove('theme-anim'),500);}
 root.setAttribute('data-theme',id);root.setAttribute('data-theme-pref',pref);readFx();
 const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',getComputedStyle(root).getPropertyValue('--bg').trim()||'#fffaf2');
}
function setTheme(pref){prefs.theme=THEMES.some(t=>t.id===pref)?pref:'confetti';save();applyTheme(prefs.theme,true);}
if(darkQuery){const onScheme=()=>{if(prefs.theme==='auto')applyTheme('auto',true);};if(darkQuery.addEventListener)darkQuery.addEventListener('change',onScheme);else if(darkQuery.addListener)darkQuery.addListener(onScheme);}
applyTheme(prefs.theme);
function themePreview(id){
 const grid='<div class="tp-board"><i class="t">5</i><i class="s">7</i><i class="p">2</i><i class="t">4</i><i class="c">3</i><i class="t">8</i><i></i><i class="s">1</i><i class="t">9</i></div>';
 if(id==='auto')return '<div class="theme-preview split" aria-hidden="true"><div class="tp-half" data-theme="confetti">'+grid+'</div><div class="tp-half" data-theme="notte">'+grid+'</div></div>';
 return '<div class="theme-preview" data-theme="'+id+'" aria-hidden="true">'+grid+'<div class="tp-side"><b></b><u></u><s></s></div></div>';
}

/* Suggerimenti giornalieri: solo in modalità Normale. Allenamento resta libero, Time Attack ha già il costo in tempo. */
const HINTS_PER_DAY=5;
function dayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function hintsLeft(){return prefs.hintsDay===dayKey()?Math.max(0,HINTS_PER_DAY-prefs.hintsUsed):HINTS_PER_DAY;}
function useDailyHint(){const k=dayKey();if(prefs.hintsDay!==k){prefs.hintsDay=k;prefs.hintsUsed=0;}prefs.hintsUsed++;save();}
function limitedHints(){return !!engine&&engine.mode==='normal'&&!tutorial;}
let primeCollection={};
try{const data=JSON.parse(localStorage.getItem('cbm-primi-collection-v1')||'{}');if(data&&typeof data==='object'&&!Array.isArray(data))for(const [key,count]of Object.entries(data)){const n=Number(key);if(/^\d+$/.test(key)&&Number.isSafeInteger(n)&&n>=2&&Number.isSafeInteger(count)&&count>0)primeCollection[n]=count;}}catch(_){storageOK=false;}
function recordPrime(value){primeCollection[value]=(primeCollection[value]||0)+1;try{localStorage.setItem('cbm-primi-collection-v1',JSON.stringify(primeCollection));}catch(_){storageOK=false;}$('storageWarning').hidden=storageOK;}
