/* Local-only localization. Text and accessible labels change in place;
   board buttons and event handlers retain their identity during arrivals. */
const LANGUAGES=[['it','Italiano'],['en','English'],['es','Español'],['fr','Français'],['de','Deutsch'],['ja','日本語']];
const LANG_LOCALES={it:'it-IT',en:'en-US',es:'es-ES',fr:'fr-FR',de:'de-DE',ja:'ja-JP'};
function language(){
 if(LANG_LOCALES[prefs.language])return prefs.language;
 for(const value of navigator.languages||[navigator.language||'en']){const code=value.toLowerCase().split('-')[0];if(LANG_LOCALES[code])return code;}
 return 'en';
}
