function updateTimer(){if(!engine)return;const timed=engine.mode!=='training'&&!tutorial,attack=engine.mode==='attack';$('countdown').textContent=timed?(attack?'+1 in ':'')+(Math.max(0,engine.remaining)/1000).toLocaleString(locale(),{minimumFractionDigits:1,maximumFractionDigits:1})+' s':'Solo dopo azione';$('timerBar').style.transform='scaleX('+(timed?Math.max(0,engine.remaining/engine.arrivalInterval):1)+')';$('timerBar').classList.toggle('low',timed&&engine.remaining<2000);if(attack){const t=Math.max(0,engine.attackRemaining);$('attackClock').innerHTML=(t/1000).toLocaleString(locale(),{minimumFractionDigits:1,maximumFractionDigits:1})+'<small>s</small>';$('attackClock').classList.toggle('low',t<=10000);$('hint').disabled=t<=5000||engine.over;if(t>0&&t<=5000&&!paused){const second=Math.ceil(t/1000);if(audio.lastWarning!==second){audio.lastWarning=second;tone('warning');}}else if(t>5000)audio.lastWarning=null;}}
