function tickFrame(ts){if(lastFrame!==null&&engine&&!paused&&!engine.over&&!tutorial){const dt=ts-lastFrame;/* Throttling is a pause, never a backlog of arrivals. */if(dt>1500){pauseGame('Gioco in pausa dopo un’interruzione.');}else{const i=engine.tick(dt);if(i>=0){markArrival(i);render();say('Nuova tessera arrivata. La tua selezione è conservata.');}updateTimer();if(engine.over){render();endGame();}}}lastFrame=ts;drawParticles(ts);requestAnimationFrame(tickFrame);}
let panelBack=null;
function modal(title,html){panelBack=null;$('modal').classList.remove('guide-modal','sheet-modal');if($('modalBack').hidden)previousFocus=document.activeElement;$('modal').innerHTML='<div class="panel-top"><span class="eyebrow">Confused By Me · Confused Prime</span></div><h2 id="modalTitle">'+title+'</h2>'+html;$('modalBack').hidden=false;$('modal').focus();$('modal').scrollTop=0;}
