function closeModal(){$('modalBack').hidden=true;panelBack=null;const target=previousFocus&&previousFocus.isConnected?previousFocus:(!$('game').hidden?$('pause'):$('homeMenu'));target?.focus();}
function resume(){if(document.hidden)return;unlockAudio();closeModal();paused=false;lastFrame=null;audio.syncMusic();}
