 modal('Menu',`<p class="menu-note">${note||'Partita in pausa. Il tempo è fermo.'}</p><div class="stack-btns"><button class="primary menu-resume" id="resume">Riprendi partita</button><button class="secondary" id="pauseSettings">Impostazioni <span aria-hidden="true">→</span></button><button class="secondary" id="menuGuide">Come si gioca <span aria-hidden="true">→</span></button><button class="secondary" id="pauseCollection">Primi creati <span aria-hidden="true">→</span></button></div><nav class="home-tools session-tools" aria-label="Questa partita"><button id="replay"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12a8 8 0 108-8H7"/><path d="M7 1.5L4.5 4 7 6.5"/></svg><span>Riprova</span></button><button id="newGame"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg><span>Nuova partita</span></button><button id="toHome"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 11l8-7 8 7"/><path d="M6 10v10h12V10"/></svg><span>Home</span></button></nav>`);
