function resultText(){return ['Confused Prime · Confused By Me',modeName(engine.mode)+' · '+fmt(engine.score)+' punti','Primo massimo: '+fmt(engine.highest),'Primi creati: '+engine.fusions+' ('+Object.keys(engine.found).length+' diversi)','Durata: '+durationText(engine.elapsedMs),'Seme: '+engine.seed+' · v1.9'].map(text=>translateText(text)).join('\n');}
