function renderTutorial(){const descriptions=['Tocca 3 come centro, poi 7 e 1. La somma è 11: premi Fondi.','Tocca un 17 e poi l’altro, in diagonale. Premi Coppia di primi: costa 578 punti.','Tocca il 4 centrale, poi gli altri due. Premi Tris uguale: costa 48 punti.'];$('tutorialBanner').innerHTML=`<strong>Prova ${tutorialStep+1} di 3 · ${['Fai crescere il centro','Recupera spazio','Anche i non primi'][tutorialStep]}</strong>${tutorialDone?['Esatto: resta 11 e guadagni 121 punti.','I due 17 scompaiono. Il punteggio è −578.','Tre 4 rimossi, −48 punti. Dopo ogni azione arriva una sola tessera.'][tutorialStep]:descriptions[tutorialStep]}${tutorialDone?'<button class="primary" id="tutorialNext">'+(tutorialStep===2?'Gioca ora':'Continua')+'</button>':'<button class="pill" id="skipTutorial">Salta tutorial</button>'}`;if(tutorialDone)$('tutorialNext').onclick=()=>{if(tutorialStep<2){tutorialStep++;loadTutorial();}else{prefs.tutorial=true;save();start(pendingMode);}};else $('skipTutorial').onclick=()=>{prefs.tutorial=true;save();start(pendingMode);};}
