   const f=document.createElement('div');f.className='float';Object.assign(f.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',fontSize:'23px',background:merge?'linear-gradient(145deg,'+FX.goodHi+','+FX.good+')':'linear-gradient(145deg,'+FX.badHi+','+FX.bad+')'});f.textContent=item.value;document.body.append(f);
