function drawParticles(ts){
 if(!ctx)return;if(fxWidth!==innerWidth||fxHeight!==innerHeight){fxWidth=innerWidth;fxHeight=innerHeight;const d=Math.min(devicePixelRatio||1,2);$('fx').width=fxWidth*d;$('fx').height=fxHeight*d;ctx.setTransform(d,0,0,d,0,0);}ctx.clearRect(0,0,fxWidth,fxHeight);const dt=Math.min((ts-lastParticleTime)/1000,.04);lastParticleTime=ts;
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt*p.decay;if(p.life<=0){particles.splice(i,1);continue;}ctx.globalAlpha=Math.min(1,p.life);ctx.fillStyle=p.color;ctx.strokeStyle=p.color;
  if(p.kind==='ring'){p.r+=p.grow*dt;ctx.lineWidth=p.width*p.life;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.stroke();continue;}
  if(p.kind==='converge'){const t=1-p.life,e=t*t;const nx=p.originX+(p.tx-p.originX)*e,ny=p.originY+(p.ty-p.originY)*e;ctx.globalAlpha=Math.sin(t*Math.PI);ctx.lineWidth=p.r;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(nx,ny);ctx.stroke();p.x=nx;p.y=ny;continue;}
  p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.gravity*dt;
  if(p.kind==='shard'){p.angle+=p.spin*dt;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillRect(-p.r,-p.r/2,p.r*2,p.r);ctx.restore();}
  else if(p.kind==='star'){const r=p.r*p.life;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-r*2,p.y);ctx.lineTo(p.x+r*2,p.y);ctx.moveTo(p.x,p.y-r*2);ctx.lineTo(p.x,p.y+r*2);ctx.stroke();}
  else{ctx.beginPath();ctx.arc(p.x,p.y,p.r*p.life,0,Math.PI*2);ctx.fill();}
 }ctx.globalAlpha=1;
}
